function setReactValue(node,value){if(!node)return;const proto=node.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,setter=Object.getOwnPropertyDescriptor(proto,'value')?.set;setter?setter.call(node,value):node.value=value;node.dispatchEvent(new Event('input',{bubbles:true}));node.dispatchEvent(new Event('change',{bubbles:true}))}
function selectContaining(select,text){if(!select)return;const option=[...select.options].find(o=>o.textContent.toLowerCase().includes(text.toLowerCase()));if(option){select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}))}}
function selectPresetOption(selectIndex,optionIndex){const select=document.querySelectorAll('.builder-section select')[selectIndex],option=select?.options[optionIndex];if(!select||!option)return;select.value=option.value;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}))}
function applyPptPreset(){const w=PPT_LINK[lang()]||PPT_LINK.English,slide=document.querySelector('.task-card.orange');if(slide&&!slide.classList.contains('selected'))slide.click();setTimeout(()=>{const builder=document.querySelector('.builder-section');if(!builder)return;if(location.hash!=='#tasks')history.replaceState(null,'','#tasks');const request=[...builder.querySelectorAll('textarea')].find(x=>!x.classList.contains('source-area')&&!x.closest('.rules-library'));setReactValue(request,w.task);setReactValue(builder.querySelector('textarea.source-area'),w.source);setReactValue(builder.querySelector('.rules-library textarea'),w.rules);setReactValue(builder.querySelector('.compact-library input'),w.output);[[1,2],[2,2],[3,0],[4,6],[5,0],[6,0],[7,2],[8,1],[9,1]].forEach(([s,o],i)=>setTimeout(()=>selectPresetOption(s,o),40+i*55));setTimeout(()=>{const number=[...document.querySelectorAll('.builder-section input')].find(x=>x.type==='number'||/slide|example:\s*\d+/i.test(x.placeholder||''));setReactValue(number,'6');focusSection(builder)},720)},260)}
function linkedPpt(){const w=PPT_LINK[lang()]||PPT_LINK.English,card=document.querySelector('#practice-slides');if(card){const title=card.querySelector('.exercise-title b'),desc=card.querySelector('.exercise-title p');if(title)title.textContent=w.title;if(desc)desc.textContent=w.desc;card.querySelector('.ux-linked-flow25')?.remove()}document.querySelector('.ux-ppt-preset25')?.remove()}

function removePracticePage(){document.querySelectorAll('.portal-card-grid>*').forEach((card,i)=>{card.hidden=i>=3});document.querySelectorAll('.portal-nav .nav-menu').forEach((item,i)=>{if(i>=3)item.setAttribute('hidden','');else item.removeAttribute('hidden')});document.querySelector('.training-hub')?.setAttribute('hidden','');document.querySelector('#workshop-legacy')?.removeAttribute('hidden');if(location.hash==='#practice')nativeGo('workshop')}
function goalLinks(){document.addEventListener('click',e=>{const g=e.target.closest('.ux-goal');if(!g)return;e.preventDefault();const text=g.innerText.toLowerCase();if(text.includes('safety')||text.includes('\u{5B89}\u{5168}')||text.includes('\u{5B89}\u{5168}')||text.includes('\u{C548}\u{C804}')){nativeGo('workshop');setTimeout(()=>focusSection(document.querySelector('#practice-risk,#training-practice')),420)}else{nativeGo('prompt');setTimeout(()=>{const cards=[...document.querySelectorAll('.task-card')],key=text.includes('excel')?'excel':text.includes('presentation')||text.includes('\u{7C21}\u{5831}')||text.includes('\u{6F14}\u{793A}')||text.includes('\u{30D7}\u{30EC}\u{30BC}\u{30F3}')||text.includes('\u{D504}\u{B808}\u{C820}')?'powerpoint':text.includes('report')||text.includes('\u{5831}\u{544A}')||text.includes('\u{62A5}\u{544A}')||text.includes('\u{30EC}\u{30DD}\u{30FC}\u{30C8}')||text.includes('\u{BCF4}\u{ACE0}')?'word':text.includes('meeting')||text.includes('\u{6703}\u{8B70}')||text.includes('\u{4F1A}\u{8BAE}')||text.includes('\u{4F1A}\u{8B70}')||text.includes('\u{D68C}\u{C758}')?'meeting':'email';cards.find(c=>c.innerText.toLowerCase().includes(key))?.click()},320)}},true)}
function intercept(){document.addEventListener('click',e=>{const copy=e.target.closest('.copy-button');if(copy){e.preventDefault();e.stopImmediatePropagation();const core=document.querySelector('.prompt-panel > pre:not(.ux-role-preview25)')?.innerText||'';navigator.clipboard?.writeText(`${profilePrompt()}\n\n${core}`);copy.innerHTML=`<span>${esc(tr().copied)}</span><b>&#10003;</b>`;setTimeout(updatePreview,1400);return}const reset=e.target.closest('.prompt-actions button');if(reset&&!reset.dataset.uxConfirmed){e.preventDefault();e.stopImmediatePropagation();if(confirm(tr().reset)){reset.dataset.uxConfirmed='1';reset.click();delete reset.dataset.uxConfirmed}}},true)}
